'use strict';
function verdictText(p){const high=p.threshold??effectiveThreshold()*100,low=(trained?.policy?.low??.2)*100;return p.score>=high?'Strong phishing indicators':p.caution?'Uncertain — verify independently':p.score<=low?'Lower URL risk':'Uncertain — verify independently'}
predictionBadge=function(p){const text=verdictText(p);return pill(text,text==='Strong phishing indicators'?'red':text==='Lower URL risk'?'':'amber')};
const scoredInference=scoreURL;
scoreURL=function(raw){const p=scoredInference(raw),u=new URL(raw);if(u.username||u.password)p.caution=`User information appears before @. The actual destination host is ${u.hostname}; text before @ is not the website host.`;return p};
const modelLatestCard=latestCard;
latestCard=function(){const p=state.predictions[0];return modelLatestCard()+(p?.caution?`<div class="panel-body"><h3>Structural caution</h3><p>${esc(p.caution)}</p></div>`:'')};
const classificationAction=action;
action=function(name){if(name==='prediction-export'){download('url-assessments.csv','url,score,assessment,model,threshold,time\n'+state.predictions.map(p=>[p.url,p.score,verdictText(p),p.model,p.threshold,p.time].map(csv).join(',')).join('\n'),'text/csv');return}if(name==='export-previous'){const previous=localStorage.getItem('sentineldrift.trained.v1');if(!previous){toast('No previous-model history exists in this browser.');return}download('sentineldrift-previous-model-history.json',previous);return}classificationAction(name)};
const originalSettings=renders.settings;
renders.settings=()=>originalSettings()+panel('Classifier update',`<div class="panel-body"><h3>Multi-source classifier v2</h3><p>The old homepage-only training bias has been replaced. This version learns from real page paths and URL-text patterns. It has three outcomes: lower URL risk, uncertain, and strong phishing indicators.</p><p>The new model uses a separate local workspace so old predictions and adaptive weights are not silently reused. The old workspace has not been deleted.</p>${btn('Export previous model history','export-previous')}<p class="help">The minimum strong-warning threshold is selected on validation data. It cannot be lowered below that tested value in this interface. Higher thresholds mean fewer strong warnings, including fewer warnings on phishing URLs.</p></div>`);
function resultMetrics(m,title){return `<div class="result"><h3>${title}</h3><div class="summary-row"><span>Legitimate URLs falsely warned</span><strong>${m.confusion?.fp??m.false_positives} / ${m.legitimate}</strong></div><div class="summary-row"><span>False-positive rate</span><strong>${((m.fpr??m.false_positive_rate)*100).toFixed(2)}%</strong></div><div class="summary-row"><span>Phishing receiving a strong warning</span><strong>${((m.recall??m.strong_warning_recall)*100).toFixed(1)}%</strong></div><div class="summary-row"><span>Phishing assigned lower URL risk</span><strong>${m.low_risk_phishing??m.phishing_assigned_lower_risk} / ${m.phishing}</strong></div><p class="help">Uncertain is not safe. Phishing URLs without a strong warning are counted as misses at the high-warning threshold, even when shown as uncertain.</p></div>`}
let publicAudit=null;
const adaptiveRegistry=renders.models;
renders.models=function(){return head('CLASSIFIER EVIDENCE','A score is evidence. Not a verdict on identity.','Measured false positives, detection tradeoffs, and a separate frozen-model audit.')+panel('Multi-source model',`<div class="panel-body">${trained?`<h3>${trained.id}</h3><p>${trained.family}. ${trained.train_rows.toLocaleString()} training URLs; ${trained.validation_rows.toLocaleString()} separate validation URLs. HTTPS itself is excluded from RF splits.</p><p>Decision bands: ≤${trained.policy.low*100}: lower URL risk; between ${trained.policy.low*100} and ${trained.policy.high*100}: uncertain; ≥${trained.policy.high*100}: strong phishing indicators. No band establishes that a website is official or safe.</p>${resultMetrics(trained.metrics,'Domain-disjoint development holdout')}${publicAudit?resultMetrics(publicAudit,'Additional frozen-model audit'):'<p>Loading audit report…</p>'}<p>${esc(trained.limitations)}</p><div class="actions"><a class="button" href="model-card.json" target="_blank" rel="noopener">Model card ↗</a><a class="button" href="classifier-audit.json" target="_blank" rel="noopener">Frozen audit ↗</a><a class="button" href="official-regressions.json" target="_blank" rel="noopener">Official-domain regression results ↗</a></div>`:'Loading model…'}</div>`)+panel('Current serving versions',`<div class="panel-body"><h3>Champion: ${esc(ops().champion)}</h3>${Object.values(ops().versions).map(v=>`<div class="result"><h3>${esc(v.id)} · ${esc(v.status)}</h3><p>Residual correction · independent gate F1 ${v.evaluation.historical.f1.toFixed(4)} · threshold ${v.threshold}</p></div>`).join('')||'<p>The multi-source baseline is serving. No adaptive correction has been promoted.</p>'}</div>`,btn('Export artifacts','export-evidence'))};
const measuredMonitoring=renders.monitoring;
renders.monitoring=()=>panel('How to read this page',`<div class="panel-body"><h3>Shift is about a batch, not whether this link is phishing.</h3><p>We compare feature distributions across your latest distinct URLs with the training reference. Low shift means similar, moderate means somewhat different, and high means substantially different under the configured PSI thresholds. None of these labels establishes that an individual URL is malicious.</p><p class="help">PSI ≤0.10: low; &gt;0.10 to 0.25: moderate; &gt;0.25: high. Small, hand-picked batches can trigger high shift. Thirty samples is a minimum guardrail, not proof of statistical reliability.</p></div>`)+measuredMonitoring();
document.querySelector('.notice').innerHTML='<span>◈</span><span><strong>Multi-source URL classifier.</strong> Lower risk ≠ verified safe. Uncertain ≠ safe. Strong indicators ≠ proof. Links are not opened; the model does not authenticate website identity.</span>';
fetch('classifier-audit.json').then(r=>{if(!r.ok)throw Error('Audit unavailable');return r.json()}).then(a=>{publicAudit=a;if(page==='models')render()}).catch(()=>{});render();
